package com.shahabsystem.livewebwallpaper;
import android.content.Context;import android.content.SharedPreferences;
public final class Prefs {private Prefs(){} private static SharedPreferences p(Context c){return c.getSharedPreferences("p",Context.MODE_PRIVATE);} public static int mode(Context c){return p(c).getInt("mode",1);} public static int speed(Context c){return p(c).getInt("speed",55);} public static int codeSpeed(Context c){return p(c).getInt("codeSpeed",55);} public static int fps(Context c){return p(c).getInt("fps",30);} public static int bg(Context c){return p(c).getInt("bg",0xFF050607);} public static int accent(Context c){return p(c).getInt("accent",0xFFFF6A00);} public static int dim(Context c){return p(c).getInt("dim",0);} public static float zoom(Context c){return p(c).getFloat("zoom",1f);} public static String url(Context c){return p(c).getString("url","https://example.com");} public static boolean hideScroll(Context c){return p(c).getBoolean("hideScroll",true);}}
